import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyHoaDon = () => {
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const [selectedMonth, setSelectedMonth] = useState(currentMonth);
    const [selectedYear, setSelectedYear] = useState(currentYear);
    const [viewRoom, setViewRoom] = useState(null);

    // 1. STATE DỮ LIỆU (Để trống để sau này nhận từ Backend)
    const [invoiceData, setInvoiceData] = useState(null); 
    const [totalReceived, setTotalReceived] = useState(0);
    const [loading, setLoading] = useState(false);

    const years = [2024, 2025, 2026];
    const months = Array.from({ length: 12 }, (_, i) => i + 1);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // 2. EFFECT GỌI BACKEND: Lấy dữ liệu tổng thể của tháng/năm đã chọn
    useEffect(() => {
        const fetchMonthlyInvoices = async () => {
            setLoading(true);
            try {
                // GIẢ LẬP GỌI API: /api/invoices?month=4&year=2026
                // const res = await axios.get(...)
                // setInvoiceData(res.data.rooms) // Dữ liệu từng phòng
                // setTotalReceived(res.data.total) // Tổng tiền cả chung cư

                setTimeout(() => {
                    setTotalReceived(selectedMonth < currentMonth ? 225000000 : 0);
                    setInvoiceData({}); // Để trống để tối ưu "Chưa có dữ liệu"
                    setLoading(false);
                }, 300);
            } catch (err) {
                setLoading(false);
            }
        };
        fetchMonthlyInvoices();
    }, [selectedMonth, selectedYear]);

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', height: '100%'
        }} className="glass-card">

            {/* Header */}
            <div style={{ padding: '20px', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexShrink: 0 }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý hoá đơn</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedMonth} onChange={(e) => {setSelectedMonth(parseInt(e.target.value)); setViewRoom(null);}} 
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold' }}>
                        {months.map(m => <option key={m} value={m}>Tháng {m}</option>)}
                    </select>
                    <select value={selectedYear} onChange={(e) => {setSelectedYear(parseInt(e.target.value)); setViewRoom(null);}} 
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold' }}>
                        {years.map(y => <option key={y} value={y}>Năm {y}</option>)}
                    </select>
                </div>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '30px', overflow: 'hidden' }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG */}
                <div className="custom-scrollbar" style={{ 
                    width: '210px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', alignContent: 'flex-start', overflowY: 'auto',
                    padding: '12px', backgroundColor: 'rgba(0,0,0,0.2)', borderRadius: '20px'
                }}>
                    {allRooms.map(room => (
                        <div 
                            key={room} 
                            onClick={() => setViewRoom(room)}
                            style={{ 
                                // Logic màu sắc sẽ dựa vào trạng thái trả về từ Backend (nếu có)
                                background: viewRoom === room ? '#8b5e5e' : 'rgba(255,255,255,0.9)', 
                                color: viewRoom === room ? '#fff' : '#333', 
                                padding: '10px 0', borderRadius: '8px', 
                                textAlign: 'center', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer',
                                transition: '0.2s'
                            }}>
                            {room}
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI: CHI TIẾT GIAO DỊCH */}
                <div style={{ 
                    flex: 1, backgroundColor: '#ffffff', borderRadius: '25px', 
                    padding: '30px', display: 'flex', flexDirection: 'column',
                    color: '#000', boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.3)', overflow: 'hidden'
                }}>

                    {/* Tổng tiền thực tế từ Backend */}
                    <div style={{ 
                        marginBottom: '20px', padding: '20px', backgroundColor: '#f8f9fa', 
                        borderRadius: '15px', borderLeft: '10px solid #8b5e5e', flexShrink: 0 
                    }}>
                        <div style={{ fontSize: '16px', fontWeight: 'bold', color: '#777' }}>Doanh thu thực tế (T{selectedMonth}/{selectedYear}):</div>
                        <div style={{ fontSize: '45px', fontWeight: '900', color: '#28a745' }}>
                            {totalReceived.toLocaleString()}đ
                        </div>
                    </div>

                    <h3 style={{ borderBottom: '2px solid #eee', paddingBottom: '15px', marginBottom: '15px', flexShrink: 0 }}>
                        {viewRoom ? `Hóa đơn phòng: ${viewRoom}` : 'Chọn phòng để kiểm tra'}
                    </h3>

                    <div style={{ flex: 1, overflowY: 'auto' }}>
                        {loading ? (
                            <div style={{ textAlign: 'center', paddingTop: '50px', color: '#999' }}>Đang truy xuất hóa đơn...</div>
                        ) : viewRoom ? (
                            invoiceData && invoiceData[viewRoom] ? (
                                // Render bảng khi có dữ liệu từ Backend
                                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                    <thead>
                                        <tr style={{ textAlign: 'left', color: '#888', fontSize: '14px' }}>
                                            <th style={{ padding: '12px' }}>Nội dung</th>
                                            <th style={{ padding: '12px' }}>Số tiền</th>
                                            <th style={{ padding: '12px' }}>Trạng thái</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {/* Sau này sẽ map qua mảng hóa đơn của phòng đó */}
                                    </tbody>
                                </table>
                            ) : (
                                // Trạng thái TRỐNG khi chưa có dữ liệu (Tháng hiện tại/tương lai)
                                <div style={{ textAlign: 'center', padding: '60px 0' }}>
                                    <div style={{ fontSize: '50px', marginBottom: '10px' }}>📄</div>
                                    <div style={{ fontSize: '18px', fontWeight: 'bold', color: '#dc3545' }}>CHƯA THANH TOÁN</div>
                                    <p style={{ color: '#999' }}>Phòng {viewRoom} chưa có giao dịch trong tháng {selectedMonth}.</p>
                                    <button style={{ 
                                        marginTop: '15px', padding: '10px 20px', borderRadius: '10px', 
                                        border: 'none', backgroundColor: '#8b5e5e', color: '#fff', cursor: 'pointer' 
                                    }}>
                                        Gửi thông báo nhắc đóng tiền
                                    </button>
                                </div>
                            )
                        ) : (
                            <div style={{ textAlign: 'center', padding: '100px 0', color: '#ccc', fontStyle: 'italic' }}>
                                Vui lòng chọn một phòng bên trái để xem lịch sử giao dịch...
                            </div>
                        )}
                    </div>
                </div>
            </div>
            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.1); border-radius: 10px; }
            `}</style>
        </div>
    );
};

export default QuanLyHoaDon;
